script:
test('rounds weighted 3.125 half even down to 3.12', function () {
  assert.deepEqual(code.calculateGpa({courses: [{gradePoints: '3.7', credits: '3'}, {gradePoints: '3.3', credits: '3'}, {gradePoints: '2.0', credits: '2'}]}), {gpa: '3.12'});
});
test('rounds exact decimal 2.675 half even up to 2.68', function () {
  assert.deepEqual(code.calculateGpa({courses: [{gradePoints: '4.0', credits: '1'}, {gradePoints: '3.0', credits: '1'}, {gradePoints: '2.0', credits: '1'}, {gradePoints: '1.7', credits: '1'}]}), {gpa: '2.68'});
});
test('rounds 3.12525 which is above halfway to 3.13', function () {
  assert.deepEqual(code.calculateGpa({courses: [{gradePoints: '3.7', credits: '3'}, {gradePoints: '3.3', credits: '3'}, {gradePoints: '2.001', credits: '2'}]}), {gpa: '3.13'});
});
test('rounds 2.67475 which is below halfway to 2.67', function () {
  assert.deepEqual(code.calculateGpa({courses: [{gradePoints: '3.5', credits: '3'}, {gradePoints: '0.199', credits: '1'}]}), {gpa: '2.67'});
});
test('returns null gpa for an empty course list', function () {
  assert.deepEqual(code.calculateGpa({courses: []}), {gpa: null});
});
test('returns null gpa when total credits are zero', function () {
  assert.deepEqual(code.calculateGpa({courses: [{gradePoints: '4', credits: '0'}, {gradePoints: '1.5', credits: '0.0'}]}), {gpa: null});
});
test('rounds a single course halfway 1.005 to even 1.00', function () {
  assert.deepEqual(code.calculateGpa({courses: [{gradePoints: '1.005', credits: '2'}]}), {gpa: '1.00'});
});
test('accepts mixed decimal forms and fractional credits and returns 2.81', function () {
  assert.deepEqual(code.calculateGpa({courses: [{gradePoints: '3', credits: '2.5'}, {gradePoints: '3.0', credits: '1'}, {gradePoints: '1.5', credits: '0.5'}]}), {gpa: '2.81'});
});
test('rounds only the final quotient and returns 1.25', function () {
  assert.deepEqual(code.calculateGpa({courses: [{gradePoints: '1.005', credits: '3'}, {gradePoints: '2.0', credits: '1'}]}), {gpa: '1.25'});
});
test('keeps a gpa when zero credit courses are mixed in and returns 3.50', function () {
  assert.deepEqual(code.calculateGpa({courses: [{gradePoints: '9.9', credits: '0'}, {gradePoints: '4.0', credits: '3'}, {gradePoints: '0.1', credits: '0'}, {gradePoints: '2.0', credits: '1'}, {gradePoints: '1.1', credits: '0.0'}]}), {gpa: '3.50'});
});
test('returns 0.00 when grade points are zero and credits are positive', function () {
  assert.deepEqual(code.calculateGpa({courses: [{gradePoints: '0', credits: '2'}, {gradePoints: '0.0', credits: '1'}]}), {gpa: '0.00'});
});
test('throws unknown field studentId when the input has an extra field', function () {
  assert.throws(function () {
    code.calculateGpa({courses: [{gradePoints: '4.0', credits: '1'}], studentId: '9'});
  }, /unknown field: studentId/);
});
test('throws unknown field title when the first course has an extra field', function () {
  assert.throws(function () {
    code.calculateGpa({courses: [{gradePoints: '4.0', credits: '1', title: 'a'}, {gradePoints: '3.0', credits: '1'}, {gradePoints: '2.0', credits: '1'}]});
  }, /unknown field: title/);
});
test('throws unknown field title when the middle course has an extra field', function () {
  assert.throws(function () {
    code.calculateGpa({courses: [{gradePoints: '4.0', credits: '1'}, {gradePoints: '3.0', credits: '1', title: 'a'}, {gradePoints: '2.0', credits: '1'}]});
  }, /unknown field: title/);
});
test('throws unknown field title when the last course has an extra field', function () {
  assert.throws(function () {
    code.calculateGpa({courses: [{gradePoints: '4.0', credits: '1'}, {gradePoints: '3.0', credits: '1'}, {gradePoints: '2.0', credits: '1', title: 'a'}]});
  }, /unknown field: title/);
});
test('throws invalid decimal gradePoints when gradePoints is a number', function () {
  assert.throws(function () {
    code.calculateGpa({courses: [{gradePoints: 3.7, credits: '3'}]});
  }, /invalid decimal: gradePoints/);
});
